#!/usr/bin/env python3
"""rc.1 fix pass, m14 data parts: route three records to the TN review queue (D-DATA; ADR-0032; DATA_FIX_BRIEF §12).

Actor-neutral wording close to cultural-protocol content has no TN sign-off on record: emst:core/CMP-2VQTX8E
("Practise cultural humility ..."), emst:core/TSK-11X9525 ("places not to enter") and emst:core/TSK-5ZRM1W1
("recognized cultural advisers"). Each goes to the TN queue with approval_status pending-tribal-review and is held
(indigenousDataFlag true, approvalStatus pending-tribal-review, sensitivity restricted-governed, aiUsePermitted false),
so every release excludes it. Records that depend on a held record through a dependent link (scripts/validate_v2.py
DEPENDENT_LINKS: tasks supporting it, its indicators, ratings of the held tasks and competency) are held by inheritance,
as the validator requires (E-TRIBAL-INHERIT). IDs stay minted and `candidate` in the registry (ADR-0010: never reused);
the build drops references to them and counts them. The queue file lists IDs only, never content.
Run: python3 -I docs/build/rc1-fix/fix_holds.py   Licence: Apache-2.0.
"""
from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import rc1lib as R  # noqa: E402

L = R.L
sys.path.insert(0, str(L.ROOT / "scripts"))
import validate_v2 as V  # noqa: E402

ROUTED = {
    # reasons name the review finding only, never the record's content (the file is "IDs only, never content")
    "emst:core/CMP-2VQTX8E": "data-method review m14: actor-neutral wording close to cultural-protocol content; no TN sign-off on record",
    "emst:core/TSK-11X9525": "data-method review m14: actor-neutral wording close to cultural-protocol content; no TN sign-off on record",
    "emst:core/TSK-5ZRM1W1": "data-method review m14: actor-neutral wording close to cultural-protocol content; no TN sign-off on record",
}
FLAGS = {"indigenousDataFlag": True, "approvalStatus": "pending-tribal-review", "aiUsePermitted": False}
QUEUE = L.GOVERNANCE / "tn_review_queue.yaml"


def closure(recs):
    held = set(ROUTED)
    while True:
        add = set()
        for rid, r in recs.items():
            if rid in held:
                continue
            for dotted in V.DEPENDENT_LINKS.get(r.get("type"), []):
                if any(x in held for x in V._get_path(r, dotted)):
                    add.add(rid)
                    break
        if not add:
            return held
        held |= add


def hold(r):
    if r.get("indigenousDataFlag") is True and r.get("approvalStatus") == "pending-tribal-review" \
            and r.get("sensitivity") == "restricted-governed":
        return None
    out = dict(r)
    out["sensitivity"] = "restricted-governed"
    prev = "sensitivity"
    for k, v in FLAGS.items():
        out = R.insert_after(out, prev, k, v) if k not in out else {**out, k: v}
        prev = k
    return out


def main():
    locs, recs = {}, {}
    for loc, r in R.records():
        if isinstance(r.get("id"), str):
            locs[r["id"]], recs[r["id"]] = loc, r
    held = closure(recs)
    inherited = sorted(held - set(ROUTED))
    jsonl = {}
    for rid in sorted(held):
        loc = locs[rid]
        if loc.path.suffix == ".yaml":
            R.edit_yaml(loc.path, hold)
        else:
            jsonl.setdefault(loc.path, set()).add(rid)
    for path, ids in sorted(jsonl.items()):
        if path.parent.name.startswith("emst-v1-"):
            continue        # generated by scripts/migrate_v1.py, which applies the same hold (apply_holds); run it next
        R.edit_jsonl(path, lambda r, ids=ids: hold(r) if r.get("id") in ids else None)
    doc = {
        "queue": "TN review queue (gate G-TN)",
        "description": ("Records routed to the TN gate reviewer. Each is held (approvalStatus pending-tribal-review) and "
                        "excluded from every release until a recorded TN review, and later the Tribal Advisory Council, "
                        "decides (ADR-0007 §D; docs/governance/tribal_gate_procedures.md §5). IDs only, never content. "
                        "Changes to this file are change type T."),
        "decidedIn": ["ADR-0032", "DATA_FIX_BRIEF §12 (data-method review m14)"],
        "items": [{"id": rid, "approval_status": "pending-tribal-review", "routedOn": R.TODAY, "routedBy": R.AGENT,
                   "reason": why} for rid, why in sorted(ROUTED.items())],
        "heldByInheritance": {"basis": "dependent links to a routed record (scripts/validate_v2.py DEPENDENT_LINKS)",
                              "count": len(inherited), "ids": inherited},
    }
    text = L.dump_yaml(doc)
    if not QUEUE.exists() or QUEUE.read_text(encoding="utf-8") != text:
        QUEUE.write_text(text, encoding="utf-8")
        R.LOG.append(str(QUEUE.relative_to(L.ROOT)))
    print(f"routed {len(ROUTED)}; held by inheritance {len(inherited)}")
    R.summary("fix_holds")


if __name__ == "__main__":
    main()
